INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1454746-ae399', 'stk-heshy', 'AE 399', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nفي هذا الموضوع بكتب عن تدريبي الصيفي , مواقف , احداث من الحياة اليومية , الشركة\n\nاسم الشركة\nعربي : طيران وفضاء اندونيسيا\nانجليزي : Indonesian aerospace\nاندونيسي: PT Dirgantara\n\nمكان الشركة :\n\nاندونيسيا , جاوة الغربية , مطار حسين ساسترانيغارا , مدينة باندونغ\n\nمجال عمل الشركة :\n\nتصميم وصناعة وصيانة وتطوير الطائرات المدنية والحربية\n\nمدة التدريب:\n\n45 يوم\nمن 29 يوليو الى 10 سبتمبر\n\nمجال التدريب:\n\nفي اول يوم في الشركة عرضو علي اقسام التخصص الستة\naerodynamics\npropulsion\nstructures and materials\nflight dynamics\nflight control\nastronautics\n\nاخترت flight dynamics بحكم سرية العمل في الـastronautics\n\nوحدد البرنامج على انه نفس عمل المهندسين الكبار, اي مهمة موجودة اخذها واطرح الحلول وتقارن مع حلول المهندسين, واذا كان الحل مناسب وصحيح يعتمد\n\nفي اليوم الثاني تم تغيير الخطة كالتالي\n\nيوجد مشروع طائرة جديدة وعرضوا علينا (4 طلاب) الدخول في تصميم الطائرة\nبدلا من حل المشاكل اليومية\n\nمع اعتماد التصميم بشكل نهائي اذا توافق مع بقية الاجزاء\nوافقنا واصدر برنامج جديد للتدريب\n\nالمشروع سري , فلا تتوقعوا الكثير من المعلومات المباشرة\n\nتابعوا هذا الموضوع للمزيد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/indonesian-aerospace-pt-dirgantara/174291/1", "user": "HESHY", "ts": 1470192266000, "tid": 174291, "pn": 1}}', 1470192266000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1510504-ae399', 'stk-chemical_engineering', 'AE 399', 'info', '{"desc": "يبن الحلال احد يفهمني هل يعطونا تذكرة طيران ولا نروح لهم كيف طبعا انا في الغريبة صعب جدا اروح بالسيارة لهم .\n\nثاني شيء هل يعطونا سكن ولا كيف لان برضو صعب نكون في الشارع وانا معرف شقق ولا عندي مواصلات هناك اتمنى احد يفيدنا .\n\nانا اخاف ان مايعطونا سكن لانهم كاتبين ان الشركة غير ملزمة بتوفير السكن اذا لم يتوفر .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181273/38", "user": "Chemical_Engineering", "ts": 1559482923000, "tid": 181273, "pn": 38}}', 1559482923000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1510518-ae399', 'stk-abdullah_96', 'AE 399', 'info', '{"desc": "التذاكر ايه اتوقع يرسلونها لنا ايميل، ارسلوا لي ملفات قبل شوي ومذكور فيه سكان الغربية على طيران ارامكو باقي المناطق يحجزون لنفسهم والشركة تعوضهم بعد التدريب.\n\nبخصوص السكن شكل مافيه ذكروا في الايميل انه لا يوجد سكن لا للطلاب ولا الطالبات ورح يصرف بدل سكن 1500 رح احاول اتواصل معهم بكرة واتأكد.\n\n( انا من جدة وتدريبي في الظهران )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181273/41", "user": "abdullah_96", "ts": 1559510043000, "tid": 181273, "pn": 41}}', 1559510043000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1510874-ae399', 'stk-abdullah_s_alm', 'AE 399', 'info', '{"desc": "اللي من ضواحي مكة كاتبين انو بتكون فيه طيارة تقلهم للاماكن النائية بس الى الان ما حجزو طيارة . تواصلت مع مكتب ارامكو قالو ما لنا دخل لازم تتواصل مع مشرفك اتصلت على المشرف وراسلته ايميل ما فيه اي رد واتصلت على طيران ارامكو قالو اصلا ما فيه رحلة يوم الجمعة نهائيا مين اللي قال انو فيه رحلة ؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181273/128", "user": "Abdullah_S_Alm", "ts": 1560284652000, "tid": 181273, "pn": 128}}', 1560284652000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1456877-ae399', 'stk-user8581', 'AE 399', 'info', '{"desc": "2 - إجرائات الجامعة / الشركة .\nطريقة التقديم : في نهاية الأسبوع العاشر من السمستر الثاني القسم يرسل للطلاب المرشحين للتدريب رسالة عن فرص تدريب بشركة JGC فيها شروط القبول في التدريب الخارجي بالإضافة لشروط الشركة .\nالشروط غالبا :\n- سعودي الجنسية ( شرط الشركة )\n- معدل 3 ( وأحيانا 2.75 )\n- ما سبق للطالب إنه طلع في برنامج التبادل الطلابي أو زيارات دولية\n- افرج قريداته في الانجلش C+\n\nوهذه هي رسالة من قسم الهندسة المدنية :\n\n[/quote]\n\n[quote]\n\nTo Summer Training Students in Term 153 :\nI want to inform you that as part of the cooperation between JGC Company (Japan) and Saudi Arabia , there is ONE opportunity for a civil Engineering student to train in Japan. The requirement to be a candidate include : CGPA & MGPA 2.75 or above , average English courses grade C+ or better, and to be a Saudi national\nIf you plan to register for CE 399 in term 153 , and are interested and satisfy the minimum requirements please contact Dr Khathlan (16-138) as soon as possible and bring with you the following;\nCGPA =\nMGPA=\nGrades in ENGL 101 , 102 & 214 =\n\nبعد اسبوع القسم يرفع أسماء الطلاب المرشحين لإدارة التدريب و عمادة شؤون الطلاب . وبعدها راح يطلب منكم سكرتير إدارة التدريب نسخة من الـ cv والجواز والأحوال عشان يرسلها للشركة … بعد أسبوعين راح تتواصل معكم الشركة ويسون معاكم مقابلة في مقر الشركة بالخبر . ( مكان الشركة )\n\nالمقابلة : تكون على حسب تخصصك وعدد الطلاب المرشحين معك : تقريبا المرشحين كانوا 6 طلاب\n3 طلاب من الهندسة المدنية : سو لهم إختبار يتكون من 3 أقسام لها علاقة بالأساسيات في CE201/CE203/ وعن structural steel لو جبت درجة سيئة في قسم structural steel علم الموظف إنك ماخذت الكورس . بعد الإختبار فيه مقابلة بسيطة والاسئلة فيها كلها شخصية مثلا قد سافرت لليابان أو برا السعودية ؟ , أهلك راضين إنك تدرب برا ؟ وش تعرف عن اليابان ؟ والهدف منها يعرف إنك مستعد وعادي عنك تطلع تدريب برا أو لا . ( طالب بس الي انقبل من الـ 3 )\n\nطالب من الهندسة الميكانيكة : المقابلة كانت شخصية وما سو له إختبار . ( مقبول )\nطالب من الهندسة الكهربائية : المقابلة كانت شخصية وماسو له اختبار . (مقبول )\nطالب من هندسة نظم التحكم والقياس ( انا 🤠 ) : المقابلة كانت شخصية وعن بعض أساسيات التخصص بدون اختبار . ( مقبول)\n\nنصيحتي في المقابلة حاول تبين له إنه عندك فكرة عن برنامج التدريب عندهم و أقسام الشركة وأنك مرن من ناحية التدريب برا السعودية وعندك فكرة عن الحياة في اليابان . اطلع على هذا الملف فيه نبذة عن الشركة وبرامج التدريب (link )\nنتائج المقابلة تعتمد على موعد المقابلة أنا علمني إني مقبول بعد المقابلة على طول أما الشباب الي من الهندسة المدنية بعد أسبوعين ردوا عليهم .\n\nبعد النتائج راح تبدأ اجرائات الشركة وفي نفس الوقت اجرائات الجامعة لكن عشان تكون الصورة واضحة راح اذكر اجرائات الشركة اول شي :\n\nاجرائات الشركة : ( الشركة متعاونة جداً والاجرائات سهلة جداً لكن السلبية الوحيدة هي لأن الاجرائات كانت على نهاية 152 فيمكن تضطر تراجعهم في الاجازة بين 152 و153 . )\n\n- بعد القبول بفترة راح يجتمع معكم موظف HR عشان يعطيكم فكرة عن البرنامج ويعطيكم خطة التدريب و تجيبوا معاكم : الجواز & الترانسكربيت & صور بقياس معين والصور بدون غطاء رأس .\n- الفحص الطبي كان مطلوب العام الماضي لكن هذي السنة ما كان مطلوب وعلى العموم لو كان مطلوب راح يعطيكم اوراق الفحص الطبي عشان تسونه في الجامعة.\n- قبل اسبوعين من موعد الرحلة راح يسلمكم الـ certificate of eligibility ماراح تقدر تدخل اليابان بدونها .\n- قبل أسبوع من التدريب راح يجتمع معاكم ويعطيكم اوراق عشان الفيزا وقبل اسبوع من موعد الرحلة راح يسلمكم الفيزا .\n- يوم الرحلة في الصباح راح يجتمع معكم ويعطيكم بعض الأوراق تحتاجونها اذا وصلتوا اليابان مثل عنوان السكن ( عشان تعبي الفورم الي يطلبه منك مكتب الهجرة او شرطة المطار …) و رقم الموظف المسؤول عنكم في اليابان .\n- راح يحددون لكم رحلةمعينة تحجزونها وغالبا تكون من البحرين الى اليابان وعلى طيران الاتحاد (طريقة الحجز في القسم الجاي)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/174559/3", "user": "user8581", "ts": 1473112694000, "tid": 174559, "pn": 3}}', 1473112694000, 1794792305, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
